// Defender for office 365  ( as written )
// ========= KQL =========
// version 0.3
// set the search term for the watch list
// ===== customisation below =====
let search_name = "defender_for_office_365";
let queryPeriod = 14d;
// list and filter last event
let LastEvent = (
    SecurityAlert
    | where ProviderName == "OATP"
    | extend alertWasCustomized = bag_has_key(todynamic(ExtendedProperties), "OriginalProductName")
    | where alertWasCustomized == false
    // ===== customisation above =====
    | where TimeGenerated between (ago(queryPeriod) .. now())
    | summarize LastEvent = max(TimeGenerated)
);
let watchlist_name  = "connector_health_wl_v1";
let safeline = datatable (SearchKey:string,lowerLimit:string )["","999h"];
// set the watch list to use
let contectorTables = materialize (_GetWatchlist(watchlist_name));
// select the entry from the watch list, and merge in safeline, to prevent errors
let TSlowerLimit = toscalar(
    contectorTables 
    | where SearchKey == search_name
    | union safeline
    | project lowerLimit
    | extend  Timelowerlimit = totimespan(lowerLimit)
    // the line below will always pick the smaller of the entries - a real watchlist entry will always be below 999h
    | summarize min(Timelowerlimit)
);
LastEvent
// only show last event if it is greater than the limit pulled from the watchlist
| where LastEvent < ago(TSlowerLimit)
| extend QC_data_health_name = search_name, QC_data_health_type = "Connector Offline", QC_data_health_limit = TSlowerLimit
| project LastEvent,
    QC_data_health_name,
    QC_data_health_type,
    QC_data_health_limit
